CREATE VIEW v50463 AS SELECT CAST('2006-09-26' AS DATE) + INTERVAL '1' DAY, 5.0 + /* Dividend is integer 5.0 + 96.1234 DIV 1,                # Dividend is decimal 5.0 + '96' DIV 1,                   # Dividend is string 5.0 + CAST('96' AS SIGNED) DIV 1,   # Dividend is function 5.0 + CAST('96' AS UNSIGNED) DIV 1 */ CAST(96 / 1 AS SIGNED), (3 << 4) + 2, 1 + 18446744073709551615, MAX(x1.v48639) + 1, (@e := 80) + 5, CAST('10:10:10' AS TIME) + INTERVAL '0.6' SECOND FROM v48636 AS x1